// Numeric references transcribed from Spacek et al.; no invented test samples or fitted soil coefficients.
export const PENETRATION_EVIDENCE={
 accessed:'2026-11-17',
 paper:{citation:'Spacek et al. (2026), IMPRESS: A Planetary Penetrator Network for Astrobiology, Prospecting, and Exploration of Mars. Astrobiology 26(9), 688–699.',doi:'https://doi.org/10.1177/15311074261471218',preprint:'https://impressmars.com/files/preprints/impress-planetary-penetrator-network-preprint-2026-08-02.pdf',supplement:'https://impressmars.com/files/preprints/impress-preprint-supplementary-tables-s1-s2-s3-2026-07-09.pdf'},
 impress:{depthM:[.2,1],depthStatus:'Mission concept emplacement range; not measured FREYA penetration',diameterM:.05,testArticleKg:1,plannedImpactMps:115,plannedDecelerationG:5200,location:'Main author preprint, sections 3.1 and 3.2.1 (PDF pages 11–14); emplacement range also in published abstract',status:'Planned test conditions, not reported impact results'},
 references:[
 {id:'metnet',name:'MetNet',massKg:[24,24],speedMps:[50,70],depthM:[.542,.542],status:'Built/tested program; table summary, not a matched shot record',location:'Table S1, PDF page 2',primary:'https://doi.org/10.5194/gi-6-103-2017'},
 {id:'lunar-a',name:'LUNAR-A',massKg:[12,13],speedMps:[300,300],depthM:[1,2],status:'Built/tested program; table summary, not a matched shot record',location:'Table S1, PDF page 3',primary:'https://doi.org/10.1016/j.asr.2007.08.022'},
 {id:'moonlite',name:'MoonLITE',massKg:[13,13],speedMps:[300,300],depthM:[2,5],status:'Full-scale trials reported; table range, not individual measurements',location:'Table S1, PDF page 3',primary:'https://doi.org/10.1016/j.pss.2007.11.005'},
 {id:'ds2',name:'Deep Space 2',massKg:[2.4,2.4],forebodyKg:.67,speedMps:[190,190],depthM:[.6,.6],status:'Design/reference depth; no recovered Mars impact telemetry',location:'Table S1, PDF page 2',primary:'https://doi.org/10.1016/S0032-0633(00)00016-7'}
 ],
 calibration:{applied:false,reason:'The sources do not supply matched FREYA geometry/material/velocity/depth shot records for the three soil cases. Aggregate mission ranges cannot identify both Poncelet coefficients. No scaling of reference depths by probe mass or speed is applied.'}
};
const range=(r,d=3)=>r[0]===r[1]?String(r[0]):r.map(x=>Number(x.toFixed(d))).join('–');
export function penetrationEvidenceMarkup({massKg=null,speedMps=null,diameterM=null,estimates=[]}={}){
 const e=PENETRATION_EVIDENCE,valid=Number.isFinite(speedMps)&&speedMps>0;
 const reference=`<h3>Spacek / IMPRESS published penetration references</h3><p><strong>IMPRESS concept emplacement range: ${range(e.impress.depthM)} m.</strong> This is a design range, not an empirical prediction for the selected probe.</p><p>The author preprint describes a ${e.impress.testArticleKg} kg, ${e.impress.diameterM*1000} mm test article and planned ${e.impress.plannedImpactMps} m/s / up-to-${e.impress.plannedDecelerationG.toLocaleString('en-US')} g drop conditions. No measured IMPRESS depth-versus-speed dataset is reported there.</p>`;
 const context=valid?`<p>Selected probe: ${massKg.toFixed(3)} kg, ${(diameterM*1000).toFixed(1)} mm; downward speed ${speedMps.toFixed(2)} m/s. Current uncalibrated screens: ${estimates.map(x=>`${x.name} ${x.depth.toFixed(3)} m`).join('; ')}. These estimates are not fitted to the references below.</p>`:'<p>Release a probe or seek to impact to compare the current model outputs with the published reference context.</p>';
 const table='<div class="table-scroll"><table><thead><tr><th>Reference</th><th>Total mass (kg)</th><th>Reference speed (m/s)</th><th>Reference depth (m)</th><th>Evidence status and location</th></tr></thead><tbody>'+e.references.map(r=>`<tr><th><a href="${r.primary}" target="_blank" rel="noopener">${r.name}</a></th><td>${range(r.massKg)}${r.forebodyKg?` (forebody ${r.forebodyKg})`:''}</td><td>${range(r.speedMps)}</td><td>${range(r.depthM)}</td><td>${r.status}. <a href="${e.paper.supplement}#page=${r.location.includes('page 3')?3:2}">${r.location}</a></td></tr>`).join('')+'</tbody></table></div>';
 return reference+context+table+`<p>${e.calibration.reason} The three material controls below remain exploratory assumptions.</p><p><a href="${e.paper.doi}">Published paper</a> · <a href="${e.paper.preprint}#page=11">Author preprint, sections 3.1–3.2.1</a> · <a href="${e.paper.supplement}#page=2">Supplementary Table S1</a> · <a href="data/revision51/penetration_evidence.json" download>Download reference values and provenance</a>. Author copies are identified by revision dates in their URLs; byte identity with publisher files is not asserted. Reviewed ${e.accessed}.</p>`;
}
